    // refraction split (u.uwC2.z) without paying for 3 taps per scale.
    let cc = clamp(vec3f(c) + vec3f(0.6, 0.0, -0.5) * (c * u.uwC2.z * 22.0), vec3f(0.0), vec3f(2.0));
